<template>
  <div class="optimization">
    <OptimizationHeader :title="title" :name="name" :status="status" />
    <div class="optimization-option">
      <ul class="optimization-option__form">
        <li class="optimization-option__item">
          <span class="optimization-option__text">Раздел</span>
          <CustomSelect
            v-model="selectPartition"
            placeholder="Автомобили"
            :options="selectPartitions"
            @updateSort="sortCategory"
          />
        </li>
        <li class="optimization-option__item">
          <span class="optimization-option__text">Город</span>
          <CustomSelectSearch
            v-model="selectedRegion"
            :options="regionOptions"
          />
        </li>
        <li class="optimization-option__item" v-if="isActive">
          <span class="optimization-option__text">фильтр</span>
          <CustomSelect
            v-model="filter"
            placeholder="Автомобили"
            :options="filters"
            @updateSort="sortfilter"
          />
        </li>
        <li class="optimization-option__item" v-if="isActive">
          <span class="optimization-option__text">Не созданные</span>
          <CheckboxUI :value="NotCreate" @update:model-value="updateCheckbox" />
        </li>
        <li class="optimization-option__more">
          <div class="optimization-option__more-btn">
            <ButtonUI
              svg="search-svg"
              text="Сформировать поиск"
              buttonClass="btn--primary"
            />
            <ButtonUI text="Сбросить" buttonClass="btn--second" />
          </div>
          <p
            class="optimization-option__more-info"
            @click="isActive = !isActive"
          >
            еще настройки
            <img
              class="optimization-option__more-svg"
              src="@/assets/images/svg/arrow.svg"
              alt="arrow"
            />
          </p>
        </li>
      </ul>
    </div>
    <div class="optimization-table__box">
      <CustomTableNew
        :itemRows="items"
        :headerRows="headerRow"
        :immersed="isNested"
        @slot-clicked="handleButtonClick"
      >
        <!-- Слот в начале строки -->
        <template #slot-start="{ item, emitEvent }">
          <ButtonUI
            v-if="!item.id.isActiv"
            svg="edit-svg"
            text="создать"
            buttonClass="btn--error"
            @click="emitEvent('redact', item)"
          />
          <ButtonUI
            v-if="item.id.isActiv"
            svg="edit-svg"
            text="изм."
            buttonClass="btn--third"
            @click="emitEvent('redact', item)"
          />
        </template>
        <!-- Слот в конце строки -->
        <template #slot-end="{ item }">
          <TableBreadcrumbs :items="item.option.items" />
        </template>
      </CustomTableNew>
    </div>
  </div>
</template>

<script setup>
import { ref, onMounted, computed } from 'vue';

import { useQueryParams } from '@/composables/useQueryParams';
import OptimizationHeader from '@/components/SEO/OptimizationHeader';
// import CustomTable from '@/components/UI/CustomTable.vue';

import CustomSelectSearch from '@/components/UI/CustomSelectSearch';
import ButtonUI from '@/components/UI/ButtonUI';
import CustomSelect from '@/components/UI/CustomSelect';
import CustomTableNew from '@/components/UI/CustomTableNew';
import CheckboxUI from '@/components/UI/CheckboxUI';
import TableBreadcrumbs from '@/components/SEO/TableBreadcrumbs';

import { getFilterOption } from '@/services/apiClient.js';
import { TESTTABLEIntersection } from '@/const/test/test.js';

import { getSeoFilterIntersection } from '@/services/apiTableAdmin.js';
import { useCityStore } from '@/store/city.js';

//
const citiesStore = useCityStore();

const filter = ref('');
const filters = ref('');
const title = ref('Фильтры');
const name = ref('Иван Иванов');
const status = ref('сейчас на странице');
const options = ref(null);
const selectedRegion = ref('');

const isActive = ref(false);

const items = ref(TESTTABLEIntersection.filterSrch);

const selectPartition = ref({
  name: 'Автомобили',
  code: '1',
});

const selectPartitions = ref(null);

const NotCreate = ref(false);
const headerRow = [
  { name: '', width: '100px', helper: false },
  { name: 'статус', width: '250px', helper: false },
  { name: 'фильтры', width: '50%', helper: false },
];
//
const regionOptions = ref([]);
const { queryParams } = useQueryParams();
//   loadQueryParamsFromRoute,
// updateQueryParams,
// buildQueryString,
const getItem = async () => {
  const data = await getSeoFilterIntersection();

  // items.value = data.data.map((item) => {
  //   return {
  //     option: { type: 'header', value: item.title, code: item.id },
  //     itemRows: item.intersections.map((intersection) => {
  //       return {
  //         redact: { slot: 'start', contenteditable: false, id: 1 },
  //         id: {
  //           value: intersection.intersection_filter_ids.reduce(
  //             (acc, item, index) => {
  //               const value = index === 2 ? 3 : item;
  //               return acc + (acc ? ', ' : '') + value;
  //             },
  //             ''
  //           ),
  //           text: null,
  //           type: 'status',
  //           isActiv: false,
  //           contenteditable: false,
  //         },
  //         option: {
  //           slot: 'end',
  //           items: intersection,
  //           contenteditable: false,
  //           id: 1,
  //         },
  //       };
  //     }),
  //   };
  // });
  filters.value = data.data.map((item) => ({
    name: item.title,
    code: item.id.toString(),
  }));
};

const getSelectFilter = async () => {
  const data = await getFilterOption();

  options.value = data.data.map((item) => ({
    label: item.title,
    value: item.id.toString(),
  }));
};

// const getFilterParameter = async () => {
//   const data = await getFilterParameterView();
// };

const handleButtonClick = (name, item) => {
  console.log(name, item);
};
const isNested = computed(() => {
  return (
    Array.isArray(items.value) &&
    items.value.length > 0 &&
    items.value[0].itemRows !== undefined &&
    items.value[0].option !== undefined
  );
});
// const chekedSort = async (option) => {
//   console.log(option);
//   items.value = TESTTABLEIntersection.filterSrch;
// };

// const chekedSort = async (option) => {
//   await filterTable.getFilterItem(option);
//   itemRow.value = filterTable.getItemRow;
// };
const getlocation = async () => {
  await citiesStore.getСities();

  regionOptions.value = citiesStore.getSelectOption;
};
const getSection = async () => {
  const data = await getFilterOption();

  selectPartitions.value = data.data.map((item) => ({
    name: item.title,
    code: item.id.toString(),
  }));
  if (queryParams.value.section_id) {
    selectPartition.value = selectPartitions.value.find(
      (el) => el.code == queryParams.value.section_id
    );
  }
};
onMounted(() => {
  getSection();
  getItem();
  getlocation();
  getSelectFilter();
});
//  getFilterParameter();
</script>

<style scoped lang="scss">
.optimization {
  display: flex;
  flex-direction: column;
  padding: 16px 24px 16px 16px;
  width: 100%;
  height: 100vh;

  @media (max-width: 1024px) {
    justify-content: space-between;
    margin-top: 60px;
    height: calc(100vh - 60px);
  }

  &-table__box {
    height: 100%;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }

  &-option {
    display: flex;
    border-radius: 4px;
    background-color: #eef9ff;
    margin: 24px 0;
    padding: 12px 24px;

    &__box {
      display: flex;
      flex-direction: column;
      width: 100%;
    }
    &__more {
      display: flex;
      align-items: center;
      gap: 20px;
      &-btn {
        display: flex;
        align-items: center;
        gap: 16px;
      }
      &-info {
        color: #3366ff;
      }
    }
    &__item {
      display: flex;
      align-items: center;
      margin-bottom: 16px;
    }

    &__text-box {
      display: flex;
    }

    &__text {
      color: #787878;
      font-weight: 400;
      font-size: 14px;
      min-width: 150px;
    }
    &__form {
      min-width: 450px;

      @media (max-width: 1024px) {
        min-width: 100%;
      }
    }
  }
}
</style>
