<template>
  <div class="table-breadcrumbs">
    <template v-for="(item, index) in normalizedItems" :key="index">
      <span class="table-breadcrumbs__item">{{ item }}</span>

      <svg
        v-if="index !== items.length - 1"
        class="table-breadcrumbs__arrow"
        width="6"
        height="10"
        viewBox="0 0 6 10"
        fill="none"
        xmlns="http://www.w3.org/2000/svg"
      >
        <path
          d="M1 9L5 5L1 1"
          stroke="#3366FF"
          stroke-width="2"
          stroke-linecap="round"
          stroke-linejoin="round"
        />
      </svg>
    </template>
  </div>
</template>

<script setup>
import { defineProps, computed } from 'vue';

const props = defineProps({
  items: {
    type: [Array, String],
    required: true,
  },
});
// если поступает текст разделяем по пробелу
const normalizedItems = computed(() => {
  if (Array.isArray(props.items)) {
    return props.items;
  }

  let titles = props.items.intersection_titles;

  if (titles.endsWith('>')) {
    titles = titles.slice(0, -1);
  }

  // Разбиваем строку по '>', удаляя пустые элементы
  return titles
    .split('>')
    .map((item) => item.trim())
    .filter((item) => item);
});
</script>

<style lang="scss">
.table-breadcrumbs {
  display: flex;
  align-items: center;
  gap: 5px;
  &__item {
    line-height: 18px;
    font-size: 14px;
    color: #323232;
  }
  &__arrow {
    flex-shrink: 0;
  }
}
</style>
